export function label(language, key) {
  return LABELS[language]?.[key] || LABELS.en[key] || key;
}

export function translate(language, key, values = {}) {
  const apiUnavailable = key.match(/^Couldn’t reach the MIRA API at (.+)\. Verify the API URL, backend listener, and CORS_ORIGINS setting\.$/);
  if (apiUnavailable) {
    key = "Couldn’t reach the MIRA API at {url}. Verify the API URL, backend listener, and CORS_ORIGINS setting.";
    values = { ...values, url: apiUnavailable[1] };
  }
  const template = MESSAGES[language]?.[key] || LABELS[language]?.[key] || key;
  return template.replace(/\{(\w+)\}/g, (match, name) => (
    Object.prototype.hasOwnProperty.call(values, name) ? values[name] : match
  ));
}

export function setLanguagePreference(language) {
  if (typeof window === "undefined") return;
  document.documentElement.lang = language;
  window.dispatchEvent(new CustomEvent("mira-language-change", { detail: language }));
}
